// Build the client-side search index for the ⌘K command palette.
//   node scripts/gen-search-index.mjs
// Produces:
//   public/search-index.json   one row per athlete: { id, name, sub, alt?, alum? }
//
// Kept out of the JS bundle on purpose — the palette fetches this file on first
// open and the service worker caches it. Regenerated by `npm run data` and as a
// `prebuild` step so it never drifts from data/athletes.json.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));

const athletes = read("data/athletes.json");
const performances = read("data/performances.json");
const events = read("data/events.json");

const eventName = new Map(events.map((e) => [e.event_id, e.event_name]));

// Top event per athlete — most performances, ties broken by lower event_id, the
// same rule lib/data.ts rosterEntries() uses for roster-card specialties.
const counts = new Map(); // athlete_id -> Map<event_id, n>
for (const p of performances) {
  let m = counts.get(p.athlete_id);
  if (!m) counts.set(p.athlete_id, (m = new Map()));
  m.set(p.event_id, (m.get(p.event_id) ?? 0) + 1);
}
const topEvent = (id) => {
  const m = counts.get(id);
  if (!m) return null;
  let best = null;
  for (const [ev, n] of m) {
    if (!best || n > best.n || (n === best.n && ev < best.ev)) best = { ev, n };
  }
  return best ? eventName.get(best.ev) ?? null : null;
};

// Mirrors lib/athlete.ts.
const isFormer = (a) => !a.active || a.status != null;
const alumniLabel = (a) => {
  if (a.status === "transferred") return "Transferred";
  if (a.graduation_year) return `Class of '${String(a.graduation_year).slice(-2)}`;
  return "Alum";
};

const byName = (a, b) =>
  a.last_name.localeCompare(b.last_name) || a.first_name.localeCompare(b.first_name);

const rows = [...athletes]
  .sort((a, b) => Number(isFormer(a)) - Number(isFormer(b)) || byName(a, b))
  .map((a) => {
    const display = `${a.nickname || a.first_name} ${a.last_name}`;
    const former = isFormer(a);
    const ev = topEvent(a.athlete_id);
    // Prefer the athlete's main event; alumni also get their class year. Fall
    // back to a plain status word for the handful with no scraped marks.
    let sub;
    if (ev) {
      sub =
        former && a.graduation_year
          ? `${ev} · Class of '${String(a.graduation_year).slice(-2)}`
          : ev;
    } else {
      sub = former ? alumniLabel(a) : "Current athlete";
    }
    const row = { id: a.athlete_id, name: display, sub };
    // let "Kristopher" find someone shown as "Kris"
    if (a.nickname && a.nickname.toLowerCase() !== a.first_name.toLowerCase()) {
      row.alt = `${a.first_name} ${a.last_name}`;
    }
    if (former) row.alum = 1;
    return row;
  });

writeFileSync(
  join(root, "public", "search-index.json"),
  JSON.stringify(rows) + "\n"
);

console.log(`wrote public/search-index.json (${rows.length} athletes)`);
